// Generated from hash-verified archived quarter scores. Never a pregame capture claim.
import {gunzipSync} from 'node:zlib';
if(typeof window!=='undefined')throw Error('NBA_QUARTER_TRAINING_SERVER_ONLY');
const freeze=x=>{if(x&&typeof x==='object'){Object.values(x).forEach(freeze);Object.freeze(x);}return x;};
export const quarterTraining=freeze(JSON.parse(gunzipSync(Buffer.from('','base64')).toString()));
